#include <pybind11/complex.h>
#include <pybind11/numpy.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <volk/volk_alloc.hh>

namespace py = pybind11;

#include <gnuradio/filter/mmse_fir_interpolator_ff.h>
// pydoc.h is automatically generated in the build directory
#include <mmse_fir_interpolator_ff_pydoc.h>

void bind_mmse_fir_interpolator_ff(py::module& m)
{

    using mmse_fir_interpolator_ff = ::gr::filter::mmse_fir_interpolator_ff;


    py::class_<mmse_fir_interpolator_ff, std::shared_ptr<mmse_fir_interpolator_ff>>(
        m, "mmse_fir_interpolator_ff", D(mmse_fir_interpolator_ff))

        .def(py::init<>(), D(mmse_fir_interpolator_ff, mmse_fir_interpolator_ff, 0))


        .def(
            "ntaps", &mmse_fir_interpolator_ff::ntaps, D(mmse_fir_interpolator_ff, ntaps))


        .def("nsteps",
             &mmse_fir_interpolator_ff::nsteps,
             D(mmse_fir_interpolator_ff, nsteps))


        .def("interpolate",
             [](const mmse_fir_interpolator_ff& self,
                const py::array_t<float, py::array::c_style | py::array::forcecast>& input,
                float mu) {
                 py::buffer_info inb = input.request();
                 if (inb.ndim != 1) {
                     throw std::invalid_argument("Input must be a 1-dimensional array or sequence");
                 }
                 if (static_cast<size_t>(inb.size) < self.ntaps()) {
                     throw std::invalid_argument(
                         "Input array must contain at least " + std::to_string(self.ntaps()) +
                         " samples (got " + std::to_string(inb.size) + ")");
                 }
                 volk::vector<float> aligned_input(self.ntaps() + 64, 0.0f);
                 const float* ptr = static_cast<const float*>(inb.ptr);
                 std::copy(ptr, ptr + self.ntaps(), aligned_input.begin());
                 return self.interpolate(aligned_input.data(), mu);
             },
             py::arg("input"),
             py::arg("mu"),
             D(mmse_fir_interpolator_ff, interpolate))

        ;


    py::module m_kernel = m.def_submodule("kernel");
}
